49	async function loadSite(job: Job) {
50	  const p = (job.payload ?? {}) as { websiteId?: string };
51	  if (!p.websiteId) throw new Error("website job: missing websiteId");
52	  const site = await db.website.findUnique({ where: { id: p.websiteId } });
53	  if (!site) throw new Error(`Website ${p.websiteId} not found`);
54	  return site;
55	}
