57	/** Load exactly the SSH fields for a server (mirrors lib/sftp usage). */
58	export async function sshServer(serverId: string): Promise<SftpServer> {
59	  const s = await db.server.findUnique({
60	    where: { id: serverId },
61	    select: {
62	      id: true,
63	      rootPassword: true,
64	      rootPasswordEnc: true,
65	      sshPort: true,
66	      dedicatedIp: { select: { address: true } },
67	    },
68	  });
69	  if (!s) throw new Error(`Server ${serverId} not found`);
70	  return s as SftpServer;
71	}
