101	export async function ensureNginx(conn: import("ssh2").Client): Promise<void> {
102	  const have = await exec(conn, "command -v nginx >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
103	  if (have.stdout.trim() !== "yes") {
104	    const prefix = await pkgInstallPrefix(conn);
105	    const inst = await exec(conn, `${prefix} nginx`, INSTALL_TIMEOUT_MS);
106	    if (inst.code !== 0) throw new Error(`nginx install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
107	  }
108	  // Ensure the sites-available/enabled layout exists (Debian/Ubuntu default).
109	  await exec(conn, "mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled", SETUP_TIMEOUT_MS);
110	}
111	
112	export async function ensurePhpFpm(conn: import("ssh2").Client, phpVersion: string): Promise<void> {
113	  assertPhp(phpVersion);
114	  const svc = `php${phpVersion}-fpm`;
115	  const have = await exec(conn, `systemctl status ${shellQuote(svc)} >/dev/null 2>&1 && echo yes || echo no`, QUICK_TIMEOUT_MS);
116	  if (have.stdout.trim() === "yes") return;
117	  const prefix = await pkgInstallPrefix(conn);
118	  // php{ver}-fpm + the common extensions apps need.
119	  const inst = await exec(
120	    conn,
121	    `${prefix} php${phpVersion}-fpm php${phpVersion}-mysql php${phpVersion}-cli php${phpVersion}-curl php${phpVersion}-gd php${phpVersion}-mbstring php${phpVersion}-xml`,
122	    INSTALL_TIMEOUT_MS
123	  );
124	  if (inst.code !== 0) throw new Error(`php-fpm install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
125	  await exec(conn, `systemctl enable --now ${shellQuote(svc)}`, SETUP_TIMEOUT_MS);
126	}
127	
128	export async function reloadNginx(conn: import("ssh2").Client): Promise<void> {
129	  const test = await exec(conn, "nginx -t", SETUP_TIMEOUT_MS);
130	  if (test.code !== 0) throw new Error(`nginx config test failed: ${(test.stderr || test.stdout).trim().slice(0, 200)}`);
131	  await exec(conn, "systemctl reload nginx || systemctl restart nginx", SETUP_TIMEOUT_MS);
132	}
