136	export async function websiteCreate(job: Job): Promise<void> {
137	  const site = await loadSite(job);
138	  try {
139	    if (REAL) {
140	      assertDomain(site.domain);
141	      assertPath(site.docRoot);
142	      if (site.phpVersion) assertPhp(site.phpVersion);
143	      const server = await sshServer(site.serverId);
144	      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
145	      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
146	      await withServerSsh(server, async (conn) => {
147	        await ensureNginx(conn);
148	        if (site.phpVersion) await ensurePhpFpm(conn, site.phpVersion);
149	        // Docroot + a friendly placeholder index.
150	        await exec(conn, `mkdir -p ${shellQuote(site.docRoot)} && chown -R www-data:www-data ${shellQuote(site.docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
151	        await execInput(
152	          conn,
153	          `cat > ${shellQuote(site.docRoot + "/index.html")}`,
154	          `<!doctype html><meta charset="utf-8"><title>${site.domain}</title><h1>${site.domain}</h1><p>Your Nxeon-hosted site is live.</p>\n`,
155	          SETUP_TIMEOUT_MS
156	        );
157	        // Write the vhost via STDIN (never as an argv token), enable, reload.
158	        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(site.domain, site.docRoot, site.phpVersion), SETUP_TIMEOUT_MS);
159	        if (site.enabled) {
160	          await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
161	        }
162	        await reloadNginx(conn);
163	      });
164	    }
165	    await db.website.update({ where: { id: site.id }, data: { status: "ACTIVE", error: null } });
166	    await notify(
167	      site.userId,
168	      `Website ${site.domain} is live`,
169	      REAL ? "Your nginx site is configured and serving." : "Your website was created (sandbox — no real VM was touched).",
170	      `/dashboard/servers/${site.serverId}?tab=control panel`
171	    );
172	  } catch (e: any) {
173	    const reason = String(e?.message ?? e).slice(0, 400);
174	    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
175	    await notify(site.userId, `Website ${site.domain} failed`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
176	  }
177	}
