179	export async function websiteToggle(job: Job): Promise<void> {
180	  const site = await loadSite(job);
181	  try {
182	    if (REAL) {
183	      assertDomain(site.domain);
184	      const server = await sshServer(site.serverId);
185	      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
186	      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
187	      await withServerSsh(server, async (conn) => {
188	        if (site.enabled) await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
189	        else await exec(conn, `rm -f ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
190	        await reloadNginx(conn);
191	      });
192	    }
193	    await db.website.update({ where: { id: site.id }, data: { status: site.enabled ? "ACTIVE" : "DISABLED", error: null } });
194	  } catch (e: any) {
195	    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
196	  }
197	}
