238	export async function websiteDelete(job: Job): Promise<void> {
239	  const site = await loadSite(job);
240	  try {
241	    if (REAL) {
242	      assertDomain(site.domain);
243	      assertPath(site.docRoot);
244	      const server = await sshServer(site.serverId);
245	      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
246	      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
247	      await withServerSsh(server, async (conn) => {
248	        await exec(conn, `rm -f ${shellQuote(link)} ${shellQuote(conf)}`, SETUP_TIMEOUT_MS);
249	        // Remove the docroot ONLY within /var/www (validated path); leave data
250	        // elsewhere untouched.
251	        if (site.docRoot.startsWith("/var/www/")) {
252	          await exec(conn, `rm -rf ${shellQuote(site.docRoot)}`, SETUP_TIMEOUT_MS);
253	        }
254	        await reloadNginx(conn).catch(() => {});
255	      });
256	    }
257	    await db.website.delete({ where: { id: site.id } });
258	  } catch (e: any) {
259	    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
260	  }
261	}
