20	/**
21	 * Control-panel DB_CREATE / DB_DELETE handlers (MySQL/MariaDB & PostgreSQL).
22	 *
23	 * Registered in worker/index.ts:
24	 *   DB_CREATE: dbCreate,
25	 *   DB_DELETE: dbDelete,
26	 *
27	 * The generated DB password is decrypted IN MEMORY from `passwordEnc`, applied
28	 * via the DB client's STDIN (never an argv token — mirrors migrate-real.ts), and
29	 * then `passwordEnc` is CLEARED. Engine is installed on first use.
30	 *
31	 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — status flips to ACTIVE and the
32	 * secret is scrubbed, exactly like the rest of the platform.
33	 */
34	
35	const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
