1	// "Build with Claude AI" worker handler — SAFE, plan-then-approve.
2	//
3	// Two phases, driven by ClaudeBuild.approved:
4	//   1. PLAN  (approved=false): ask Claude — with the OWNER'S effective key — for
5	//      an ordered JSON array of non-destructive shell commands. Store it to
6	//      ClaudeBuild.plan and set AWAITING_APPROVAL. NOTHING is executed.
7	//   2. EXECUTE (approved=true): run each approved command over SSH, enforcing a
8	//      denylist, a per-command timeout, and a hard command cap. Append output to
9	//      ClaudeBuild.log, then set DONE (or FAILED on error). Never runs a command
10	//      that was not part of the approved plan.
11	//
12	// This handler is wired into worker/index.ts's `handlers` map by the
13	// orchestrator (see INTEGRATION NEEDED in the final report):
14	//   import { claudeBuild } from "./claude";
15	//   CLAUDE_BUILD: claudeBuild,
16	
17	import { execFile } from "node:child_process";
18	import { promisify } from "node:util";
19	import { db } from "../lib/db";
20	import { askClaude, effectiveKeyFor, type ClaudeMessage } from "../lib/anthropic";
21	import { SANDBOX } from "../lib/sandbox";
22	import { serverRootPassword } from "../lib/sftp";
23	import type { Job } from "@prisma/client";
24	
25	const execFileAsync = promisify(execFile);
26	
27	/** Hard cap on the number of commands executed for a single build. */
28	export const CLAUDE_MAX_COMMANDS = 20;
29	
30	/** Per-command SSH execution timeout. */
31	const CMD_TIMEOUT_MS = 120_000;
32	/** Cap on captured output per command (chars) to keep the log bounded. */
33	const MAX_OUTPUT_CHARS = 4000;
34	/** Cap on total stored log size. */
35	const MAX_LOG_CHARS = 60_000;
36	
37	type PlanStep = { cmd: string; intent: string };
38	
39	const PLAN_SYSTEM_PROMPT = `You are an expert Linux server administrator. You are given a goal for a SINGLE Debian/Ubuntu server that you operate on over SSH as root. Produce a PLAN — do NOT run anything.
40	
41	Output ONLY a JSON array of steps and NOTHING else (no markdown, no backticks, no prose before or after). Each step is an object:
42	{"cmd": "<one non-interactive shell command>", "intent": "<short plain-English explanation of what it does and why>"}
43	
44	Rules for the plan:
45	- Operate ONLY on this one server. Never touch other hosts, networks, or cloud APIs.
46	- Commands must be non-interactive: use flags like -y and DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
47	- NON-DESTRUCTIVE ONLY. Absolutely no whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff/halt, no user/password changes, no disabling SSH.
48	- Keep each command self-contained and idempotent where possible.
49	- Prefer standard packages and services (apt, systemctl, nginx, ufw, etc.).
50	- At most ${CLAUDE_MAX_COMMANDS} steps. If the goal cannot be met safely, return an empty array [].`;
