52	/** Escape a string for safe single-quoted inclusion in a bash -c argument. */
53	function shSingleQuote(s: string): string {
54	  return `'${s.replace(/'/g, `'\\''`)}'`;
55	}
56	
57	/** Reject catastrophic commands as a defense-in-depth backstop (denylist). */
58	function isForbidden(cmd: string): boolean {
59	  const c = cmd.toLowerCase();
60	  const patterns = [
61	    /rm\s+(-[a-z]*\s+)*(-[a-z]*r[a-z]*f|-[a-z]*f[a-z]*r)\s+\/(\s|$)/, // rm -rf /
62	    /\bmkfs\b/,
63	    /\bfdisk\b/,
64	    /\bparted\b/,
65	    /\bdd\b[^|]*of=\/dev\//, // dd of=/dev/*
66	    /\b(reboot|shutdown|poweroff|halt|init\s+0|init\s+6)\b/,
67	    /\bshred\b/,
68	    /\bpasswd\b/,
69	    /:\(\)\s*\{.*\};:/, // fork bomb :(){ :|:& };:
70	    />\s*\/dev\/sd[a-z]/,
71	    /\bsystemctl\s+(stop|disable|mask)\s+(ssh|sshd)\b/,
72	  ];
73	  return patterns.some((p) => p.test(c));
74	}
