278	export async function removeApp(id: string): Promise<Result> {
279	  try {
280	    const { user, app } = await ownedApp(id);
281	    const limited = throttle(user.id, "remove", 10);
282	    if (limited) return { ok: false, error: limited };
283	    if (app.status === "INSTALLING") return { ok: false, error: "This app is still installing — try again shortly." };
284	
285	    // Tear down the provisioned site + database via their own worker jobs, then
286	    // drop the AppInstall record. The site/db rows carry the SSH cleanup.
287	    if (app.websiteId) {
288	      const site = await db.website.findUnique({ where: { id: app.websiteId } });
289	      if (site) {
290	        await db.website.update({ where: { id: site.id }, data: { status: "DELETING", appSlug: null } });
291	        await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: app.serverId, payload: { websiteId: site.id } } });
292	      }
293	    }
294	    if (app.databaseId) {
295	      const database = await db.vpsDatabase.findUnique({ where: { id: app.databaseId } });
296	      if (database) {
297	        await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "DELETING" } });
298	        await db.job.create({ data: { type: "DB_DELETE", serverId: app.serverId, payload: { databaseId: database.id } } });
299	      }
300	    }
301	    await db.appInstall.delete({ where: { id } });
302	    await db.auditLog.create({
303	      data: { userId: user.id, action: "cpanel.app.remove", detail: `${app.appSlug} (${app.domain})` },
304	    });
305	    revalidatePath(`/dashboard/servers/${app.serverId}`);
306	    return { ok: true };
307	  } catch (err) {
308	    return { ok: false, error: safeError(err) };
309	  }
310	}
