169	export async function listBuilds(serverId?: string) {
170	  const user = await requireUser();
171	  return db.claudeBuild.findMany({
172	    where: { userId: user.id, ...(serverId ? { serverId } : {}) },
173	    orderBy: { createdAt: "desc" },
174	    take: 20,
175	    include: { server: { select: { hostname: true } } },
176	  });
177	}
