3	/**
4	 * Control panel — Databases.
5	 *
6	 * Create/list/delete MySQL/MariaDB & PostgreSQL databases + DB users on the VPS.
7	 * The generated password is returned to the caller ONCE (shown with a copy
8	 * button in the UI) and stored only transiently (encrypted, `passwordEnc`) so
9	 * the worker can apply it; worker/databases.ts clears it after the create. The
10	 * engine is installed on first use. Sandbox-gated real work lives in the worker.
11	 */
12	import { revalidatePath } from "next/cache";
13	import { db } from "./db";
14	import { requireUser } from "./auth";
15	import { checkRateLimit } from "./rate-limit";
16	import { encryptSecret } from "./crypto-box";
17	import { IDENT_RE, generateStrongPassword } from "./ssh-exec";
18	import { DB_ENGINES, type DbEngine, type DatabaseRow } from "./cpanel-types";
19	
20	type CreateResult =
21	  | { ok: true; id: string; name: string; dbUser: string; password: string }
22	  | { ok: false; error: string };
23	type Result = { ok: true } | { ok: false; error: string };
24	
25	const EXCLUSIVE_JOBS = [
26	  "PROVISION",
27	  "REINSTALL",
28	  "DELETE",
29	  "RESIZE",
30	  "SUSPEND",
31	  "UNSUSPEND",
32	  "SNAPSHOT_ROLLBACK",
33	  "BACKUP_RESTORE",
34	  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
35	  // control-panel operations out of the way while the root filesystem is resized.
36	  "DISK_EXPAND",
37	] as const;
38	
39	async function ownedServer(serverId: string) {
40	  const user = await requireUser();
41	  const server = await db.server.findUnique({
42	    where: { id: serverId },
43	    select: { id: true, userId: true, status: true, hostname: true },
44	  });
45	  if (!server) throw new Error("Not found");
46	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
47	  return { user, server };
48	}
49	
50	async function ownedDatabase(id: string) {
51	  const user = await requireUser();
52	  const database = await db.vpsDatabase.findUnique({ where: { id } });
53	  if (!database) throw new Error("Not found");
54	  if (database.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
55	  return { user, database };
56	}
57	
58	function throttle(userId: string, op: string, max: number): string | null {
59	  const rl = checkRateLimit(`cpanel:db:${op}:${userId}`, { max, windowMs: 60_000 });
60	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
61	}
62	
63	async function lifecycleBusy(serverId: string): Promise<boolean> {
64	  const n = await db.job.count({
65	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
66	  });
67	  return n > 0;
68	}
69	
70	function safeError(err: unknown): string {
71	  const msg = err instanceof Error ? err.message : String(err);
72	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
73	  return msg.slice(0, 300);
74	}
75	
76	function rowOut(d: {
77	  id: string;
78	  engine: string;
79	  name: string;
80	  dbUser: string;
81	  status: string;
82	  error: string | null;
83	  createdAt: Date;
84	}): DatabaseRow {
85	  return {
86	    id: d.id,
87	    engine: d.engine,
88	    name: d.name,
89	    dbUser: d.dbUser,
90	    status: d.status,
91	    error: d.error,
92	    createdAt: d.createdAt.toISOString(),
93	  };
94	}
95	
96	// ---------------------------------------------------------------------------
97	
98	export async function listDatabases(
99	  serverId: string
100	): Promise<{ ok: true; databases: DatabaseRow[] } | { ok: false; error: string }> {
101	  try {
102	    const { server } = await ownedServer(serverId);
103	    const rows = await db.vpsDatabase.findMany({
104	      where: { serverId: server.id },
105	      orderBy: { createdAt: "desc" },
106	    });
107	    return { ok: true, databases: rows.map(rowOut) };
108	  } catch (err) {
109	    return { ok: false, error: safeError(err) };
110	  }
111	}
112	
113	export async function createDatabase(
114	  serverId: string,
115	  engine: string,
116	  nameInput: string,
117	  userInput: string
118	): Promise<CreateResult> {
119	  try {
120	    const { user, server } = await ownedServer(serverId);
121	    const limited = throttle(user.id, "create", 10);
122	    if (limited) return { ok: false, error: limited };
123	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to create a database." };
124	    if (await lifecycleBusy(server.id))
125	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
126	
127	    if (!(DB_ENGINES as readonly string[]).includes(engine))
128	      return { ok: false, error: "Choose a supported database engine." };
129	    const name = String(nameInput ?? "").trim();
130	    const dbUser = String(userInput ?? "").trim();
131	    if (!IDENT_RE.test(name))
132	      return { ok: false, error: "Database name: 1–32 letters, digits or underscores." };
133	    if (!IDENT_RE.test(dbUser))
134	      return { ok: false, error: "User name: 1–32 letters, digits or underscores." };
135	
136	    const existing = await db.vpsDatabase.findFirst({
137	      where: { serverId: server.id, engine, name },
138	    });
139	    if (existing) return { ok: false, error: `A ${engine} database named "${name}" already exists.` };
140	
141	    const count = await db.vpsDatabase.count({ where: { serverId: server.id } });
142	    if (count >= 50) return { ok: false, error: "Database limit reached (50 per server)." };
143	
144	    const password = generateStrongPassword(20);
145	    const row = await db.vpsDatabase.create({
146	      data: {
147	        userId: user.id,
148	        serverId: server.id,
149	        engine: engine as DbEngine,
150	        name,
151	        dbUser,
152	        passwordEnc: encryptSecret(password),
153	        status: "PENDING",
154	      },
155	    });
156	    await db.job.create({ data: { type: "DB_CREATE", serverId: server.id, payload: { databaseId: row.id } } });
157	    await db.auditLog.create({
158	      data: { userId: user.id, action: "cpanel.db.create", detail: `${engine}/${name} on ${server.hostname}` },
159	    });
160	    revalidatePath(`/dashboard/servers/${serverId}`);
161	    // Password returned ONCE — never stored in plaintext, never re-shown.
162	    return { ok: true, id: row.id, name, dbUser, password };
163	  } catch (err) {
164	    return { ok: false, error: safeError(err) };
165	  }
166	}
167	
168	export async function deleteDatabase(id: string): Promise<Result> {
169	  try {
170	    const { user, database } = await ownedDatabase(id);
171	    const limited = throttle(user.id, "delete", 15);
172	    if (limited) return { ok: false, error: limited };
173	    await db.vpsDatabase.update({ where: { id }, data: { status: "DELETING" } });
174	    await db.job.create({ data: { type: "DB_DELETE", serverId: database.serverId, payload: { databaseId: id } } });
175	    await db.auditLog.create({
176	      data: { userId: user.id, action: "cpanel.db.delete", detail: `${database.engine}/${database.name}` },
177	    });
178	    revalidatePath(`/dashboard/servers/${database.serverId}`);
179	    return { ok: true };
180	  } catch (err) {
181	    return { ok: false, error: safeError(err) };
182	  }
183	}
